{"task_id": "T30", "code": "def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    Implements the standard algorithm using a stack.
    """
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            # Skip empty components and current directory references
            continue
        if part == '..':
            # Pop the last valid directory if possible
            if stack:
                stack.pop()
            # If stack empty, we stay at root (do nothing)
        else:
            # Normal directory name
            stack.append(part)
    # Reconstruct the simplified path
    return '/' + '/'.join(stack) if stack else '/'
