def solve(matrix):
    # Determinant using Bareiss algorithm (fraction-free Gaussian elimination)
    if not matrix:
        return 1
    n = len(matrix)
    # ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # make a deep copy to avoid mutating input
    A = [list(row) for row in matrix]
    sign = 1
    for k in range(n - 1):
        # pivot handling: if pivot is zero, swap with a lower row
        if A[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            sign = -sign
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            # zero out the column below the pivot for clarity (not needed for determinant)
            A[i][k] = 0
    det = sign * A[n - 1][n - 1]
    return det

