def solve(strings):
    from collections import defaultdict
    groups = defaultdict(list)
    for s in strings:
        groups[''.join(sorted(s))].append(s)
    result = []
    for lst in groups.values():
        result.append(sorted(lst))
    result.sort()
    return result

