def solve(grid):
    if not grid:
        return 0
    m = len(grid)
    n = len(grid[0]) if grid[0] else 0
    visited = [[False]*n for _ in range(m)]
    def dfs(i,j):
        stack = [(i,j)]
        while stack:
            x,y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny]==1:
                    stack.append((nx,ny))
    count = 0
    for i in range(m):
        for j in range(n):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count += 1
    return count

def solve(matrix):
    """Return the determinant of a square integer matrix.
    Uses the Bareiss fraction‑free Gaussian elimination algorithm, which
    works entirely with integers and avoids intermediate fractions.
    An empty matrix is defined to have determinant 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure the matrix is square; if not, treat as invalid and return 0.
    for row in matrix:
        if len(row) != n:
            return 0
    # Copy to avoid mutating the input
    A = [list(row) for row in matrix]
    sign = 1
    for k in range(n - 1):
        # Pivot handling – if the current pivot is zero, swap with a lower row.
        if A[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            sign = -sign
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update ensures the division is exact.
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            A[i][k] = 0  # optional cleanup
    return sign * A[n - 1][n - 1]

