def solve(a, x):
    """Return the leftmost index to insert x into sorted list a.
    Uses binary search, works for empty list and duplicates.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

