def solve(path):
    # Simplify Unix path, handling both absolute and relative paths.
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for p in parts:
        if p == '' or p == '.':
            continue
        if p == '..':
            if stack:
                stack.pop()
            else:
                if not is_abs:
                    # keep leading .. for relative paths
                    stack.append('..')
                # else ignore when at root
        else:
            stack.append(p)
    if is_abs:
        return '/' + '/'.join(stack) if stack else '/'
    else:
        return '/'.join(stack) if stack else '.'

