{"task_id": "T48", "code": "import heapq

def solve(n, edges):
    # Build adjacency list and indegree count
    adj = [[] for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        if a<0 or a>=n or b<0 or b>=n:
            continue
        adj[a].append(b)
        indeg[b] += 1
    # Min-heap of nodes with indegree 0
    heap = [i for i in range(n) if indeg[i]==0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v]==0:
                heapq.heappush(heap, v)
    if len(order)!=n:
        return []
    return order"}

