def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount` using unlimited
    supply of each coin in `coins`. Return -1 if impossible.
    Uses a bottom‑up DP.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array where dp[i] = min coins for amount i
    INF = amount + 1  # any value > amount is effectively infinity
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non‑positive coin values
        for v in range(coin, amount + 1):
            # If we can make v-coin, then we can make v by adding this coin
            if dp[v - coin] + 1 < dp[v]:
                dp[v] = dp[v - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

