def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount* using unlimited
    coins from *coins*. If impossible, return -1.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Remove non-positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # DP array where dp[i] = min coins to achieve i
    INF = amount + 1  # larger than any possible count
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # try using coin c
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

