    if not coins:
        return -1
    # DP array where dp[i] = min coins to make amount i
    INF = amount + 1  # larger than any possible answer
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
