def solve(coins, amount):
    # Handle non-integer or negative amount gracefully
    if not isinstance(amount, int) or amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive and duplicate coin values
    filtered = {c for c in coins if isinstance(c, int) and c > 0}
    if not filtered:
        return -1
    # Use DP to compute minimum coins
    max_val = amount + 1  # sentinel for unreachable
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = max_val
        for c in filtered:
            if c <= a:
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != max_val else -1

